"""Measure original pedestrian footprints in the direction-relative crosswalk halves.

This reports geometry and source status, never a practicability or legal verdict.
"""
import hashlib
import json
import math
from pathlib import Path

RATE_HZ = 20
FRAMES = 240


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def vec(value, name):
    if not isinstance(value, list) or len(value) != 2:
        raise ValueError('Missing original '+name)
    out = tuple(float(x) for x in value)
    if not all(math.isfinite(x) for x in out):
        raise ValueError('Nonfinite original '+name)
    return out


def measure(samples_path, context_path):
    samples_path, context_path = Path(samples_path), Path(context_path)
    for path in (samples_path, context_path):
        if not path.is_file():
            raise ValueError('Missing required source: '+path.name)
    context = json.loads(context_path.read_text())
    if context.get('source_kind') not in ('synthetic_scene_request', 'native_observation'):
        raise ValueError('Unrecognized crosswalk context provenance')
    if not context.get('crosswalk_id') or not isinstance(context.get('practicability_facts'), list):
        raise ValueError('Missing crosswalk identity or practicability source fields')
    if context['source_kind'] == 'native_observation' and (
        not context.get('native_map_sha256') or type(context.get('observed_frame_count')) is not int
    ):
        raise ValueError('Native crosswalk context lacks map/frame provenance')
    center = vec(context.get('crosswalk_center_xy_m'), 'crosswalk center')
    forward = vec(context.get('crosswalk_passage_forward_xy'), 'crosswalk passage direction')
    if abs(math.hypot(*forward)-1) > .001:
        raise ValueError('Crosswalk passage direction must be unit length')
    length, width = context.get('crosswalk_length_m'), context.get('crosswalk_width_m')
    if any(type(v) not in (int, float) or not math.isfinite(v) or v <= 0 for v in (length, width)):
        raise ValueError('Invalid original crosswalk dimensions')
    rows = [json.loads(line) for line in samples_path.read_text().splitlines() if line.strip()]
    if len(rows) != FRAMES:
        raise ValueError('Full 12-second original crossing source required')
    if context['source_kind'] == 'native_observation' and context['observed_frame_count'] != len(rows):
        raise ValueError('Native crosswalk frame count differs from samples')
    frames, times, x_positions, inside, classifications = [], [], [], [], []
    right = (forward[1], -forward[0])
    for row in rows:
        frame, t = row.get('native_frame'), row.get('time_s')
        if type(frame) is not int or frame < 0 or type(t) not in (int, float) or not math.isfinite(t):
            raise ValueError('Invalid original frame/time')
        if frames and (frame != frames[-1]+1 or abs(t-times[-1]-1/RATE_HZ) > .002):
            raise ValueError('Original crosswalk frame/time order or rate invalid')
        if row.get('crosswalk_id') != context['crosswalk_id']:
            raise ValueError('Original crosswalk identity differs')
        pose = vec(row.get('pedestrian_xy_m'), 'pedestrian position')
        heading = vec(row.get('pedestrian_forward_xy'), 'pedestrian heading')
        if abs(math.hypot(*heading)-1) > .01 or sum(a*b for a,b in zip(heading,forward)) < .98:
            raise ValueError('Original pedestrian heading differs from passage direction')
        speed = row.get('speed_mps')
        if type(speed) not in (int,float) or not math.isfinite(speed) or speed < .2:
            raise ValueError('Pedestrian must be moving through the crosswalk')
        body = row.get('pedestrian_footprint_xy_m')
        if not isinstance(body,list) or len(body) != 4:
            raise ValueError('Missing original pedestrian footprint')
        points = [vec(p,'pedestrian footprint') for p in body]
        if len({(round(x,6),round(y,6)) for x,y in points}) != 4:
            raise ValueError('Degenerate original pedestrian footprint')
        centroid = (sum(p[0] for p in points)/4, sum(p[1] for p in points)/4)
        if math.dist(centroid,pose) > .05:
            raise ValueError('Original footprint does not match pedestrian pose')
        def projections(p):
            delta = (p[0]-center[0], p[1]-center[1])
            return sum(a*b for a,b in zip(delta,forward)), sum(a*b for a,b in zip(delta,right))
        longitudinal, lateral = projections(pose)
        footprints = [projections(p) for p in points]
        if all(abs(u) <= length/2+1e-6 and abs(v) <= width/2+1e-6 for u,v in footprints):
            inside.append(frame)
            if all(v > .01 for _,v in footprints):
                classifications.append('right')
            elif all(v < -.01 for _,v in footprints):
                classifications.append('left')
            else:
                classifications.append('center_or_straddling')
        frames.append(frame); times.append(t); x_positions.append(longitudinal)
    if len(inside) < RATE_HZ*3 or min(x_positions) > -length/2 or max(x_positions) < length/2:
        raise ValueError('Original pedestrian did not traverse the full crosswalk')
    if x_positions[-1] <= x_positions[0] or any(b < a-.02 for a,b in zip(x_positions,x_positions[1:])):
        raise ValueError('Original crosswalk passage is not forward')
    counts = {label:classifications.count(label) for label in ('right','left','center_or_straddling')}
    dominant = max(counts,key=counts.get)
    if counts[dominant] != len(inside):
        dominant = 'mixed'
    return {
        'format':'c10316-crosswalk-half-observation-v1',
        'source_sha256':{samples_path.name:sha(samples_path),context_path.name:sha(context_path)},
        'original_frames':len(rows),'crosswalk_frames':len(inside),
        'crosswalk_first_frame':inside[0],'crosswalk_last_frame':inside[-1],
        'crosswalk_half_counts':counts,'observed_half':dominant,
        'passage_duration_s':round(len(rows)/RATE_HZ,3),
        'context_status':('native_observed_limited' if context['source_kind']=='native_observation'
                          else 'requested_not_observed'),
        'practicability_verified':False,'legal_verdict_claimed':False}

"""Source-bound C10316 retry metrics; synthetic proof never certifies Native pixels."""
import hashlib
import json
import math
from pathlib import Path


def measure(source, expected_sha256):
    source = Path(source)
    if hashlib.sha256(source.read_bytes()).hexdigest() != expected_sha256:
        raise ValueError('Changed fallback observation source')
    values = [json.loads(line) for line in source.read_text().splitlines()]
    if len(values) != 240 or any(row.get('source_kind') != 'synthetic_cpu_fixture' for row in values):
        raise ValueError('Synthetic retry proof requires 240 provenance-marked frames')
    previous = -1
    first_clearance = None
    tracking_exceedances = 0
    visible = {'approach': 0, 'reference_corner': 0}
    for index, row in enumerate(values):
        if row.get('native_frame') != index + 100 or row.get('time_s') != round(index / 20, 4):
            raise ValueError('Fallback observation frame/time join differs')
        if row['native_frame'] <= previous:
            raise ValueError('Fallback observation frame order differs')
        previous = row['native_frame']
        pose = row.get('pedestrian_xy_m')
        body = row.get('pedestrian_footprint_xy_m')
        if not isinstance(pose, list) or len(pose) != 2 or not isinstance(body, list) or len(body) != 4:
            raise ValueError('Missing pedestrian body source')
        if any(not isinstance(v, (int, float)) or not math.isfinite(v)
               for point in [pose, *body] for v in point):
            raise ValueError('Nonfinite pedestrian body source')
        if index == 0:
            first_clearance = max(0, -2 - max(point[0] for point in body))
        requested = row.get('requested_xy_m')
        if not isinstance(requested, list) or len(requested) != 2:
            raise ValueError('Missing requested pedestrian path')
        tracking_exceedances += math.dist(pose, requested) > .2
        views = row.get('synthetic_camera_annotation')
        if not isinstance(views, dict) or set(views) != set(visible):
            raise ValueError('Missing two-view synthetic annotation')
        for role, flag in views.items():
            if type(flag) is not bool:
                raise ValueError('Invalid synthetic visibility annotation')
            visible[role] += flag
    fractions = {role: count / 240 for role, count in visible.items()}
    return {'format': 'c10316-synthetic-fallback-measurement-v1',
            'source_kind': 'synthetic_cpu_fixture', 'source_sha256': expected_sha256,
            'spawn_clearance_m': first_clearance,
            'path_error_frames_over_0_2_m': tracking_exceedances,
            'camera_visible_fraction': fractions,
            'fallback1_trigger': first_clearance < 1,
            'fallback2_trigger': tracking_exceedances >= 10,
            'fallback3_trigger': any(value < .95 for value in fractions.values()),
            'original_native_observed': False, 'original_pixels_observed': False}

"""Saved original-source C10316 finalization without a practicability verdict."""
import json
import math
from pathlib import Path
import subprocess

from measure_crosswalk import measure,sha


def required(folder,name):
    path=Path(folder)/name
    if not path.is_file():raise ValueError('Missing required source: '+name)
    return path


def rows(folder,name):
    return [json.loads(line) for line in required(folder,name).read_text().splitlines() if line.strip()]


def crosswalk_passage(folder):
    folder=Path(folder)
    return measure(folder/'native_samples.jsonl',folder/'crosswalk-context.json')


def analysis_report(folder,contract=None):
    folder=Path(folder)
    config=json.loads(required(folder,'config.json').read_text())
    if contract is None:
        contract={'case_id':config['case_id'],
                  'requirements':[{'output_key':'right_half_passage','method':'crosswalk_passage',
                                   'inputs':['native_samples.jsonl','crosswalk-context.json']},
                                  {'output_key':'marked_crosswalk_passage','method':'crosswalk_passage',
                                   'inputs':['native_samples.jsonl','crosswalk-context.json']}]}
    observation=crosswalk_passage(folder)
    values={}
    for row in contract['requirements']:
        if row['method'] not in ('crosswalk_passage','measure'):
            raise ValueError('Unrecognized C10316 measurement method')
        values[row['output_key']]={'method':row['method'],'value':observation,
                                   'sources':{name:sha(required(folder,name)) for name in row['inputs']}}
    return {'format':'worker-analysis-report-v1','case_id':contract['case_id'],
            'measurements':values,'scope':'source_bound_crosswalk_half_without_practicability_verdict'}


def verify_original_joins(folder,count):
    names=('trace.jsonl','capture/evidence.jsonl','video_frames.jsonl',
           'native_samples.jsonl','capture/native/frames.jsonl')
    trace,evidence,mapping,samples,native=(rows(folder,name) for name in names)
    if any(len(source)!=count for source in (trace,evidence,mapping,samples,native)):
        raise ValueError('Original trace/evidence/Native/frame counts differ')
    previous_frame,previous_time=-1,-math.inf
    for index,(t,e,m,s,n) in enumerate(zip(trace,evidence,mapping,samples,native)):
        frame,time=m.get('native_frame'),m.get('time_s')
        if type(frame) is not int or type(time) not in (int,float) or frame<=previous_frame or time<=previous_time:
            raise ValueError('Original frame/time order invalid')
        if m.get('video_frame')!=index or m.get('carla_frame')!=frame:
            raise ValueError('Original camera frame mapping invalid')
        if any(item!=frame for item in (t.get('frame'),e.get('original_frame'),
                                       s.get('native_frame'),n.get('frame'))):
            raise ValueError('Original Native frame join differs')
        if any(abs(float(item)-time)>1e-4 for item in
               (t['time_s'],e['recording_time_s'],s['time_s'])):
            raise ValueError('Original Native timestamp join differs')
        evidence_body={(round(v[0],3),round(v[1],3)) for v in e['ego']['body_vertices_m']}
        sample_body={(round(v[0],3),round(v[1],3)) for v in s['pedestrian_footprint_xy_m']}
        if len(evidence_body)!=4 or evidence_body!=sample_body:
            raise ValueError('Original pedestrian footprint differs from captured evidence')
        previous_frame,previous_time=frame,time
    capture=json.loads(required(folder,'capture/manifest.json').read_text())
    if capture.get('extraction_confirmed') is not True or capture.get('frames')!=count:
        raise ValueError('Original capture extraction incomplete')
    return {'frames':count,'first_frame':mapping[0]['native_frame'],
            'last_frame':mapping[-1]['native_frame'],
            'source_hashes':{name:sha(Path(folder)/name) for name in names}}


def video_info(path):
    path=Path(path)
    if not path.is_file():raise ValueError('Missing required source: '+path.name)
    probe=subprocess.run(['ffprobe','-v','error','-count_frames','-select_streams','v:0',
                          '-show_entries','stream=width,height,nb_read_frames',
                          '-of','json',str(path)],text=True,stdout=subprocess.PIPE,
                         stderr=subprocess.PIPE,timeout=120)
    if probe.returncode:raise ValueError('Source video decode failed: '+path.name)
    streams=json.loads(probe.stdout).get('streams',[])
    if len(streams)!=1 or not str(streams[0].get('nb_read_frames','')).isdigit():
        raise ValueError('Source video frame count missing: '+path.name)
    return (int(streams[0]['nb_read_frames']),int(streams[0]['width']),int(streams[0]['height']))


def finalize(attempt,output):
    from worker_exchange.native_output import validate_result
    attempt,output=Path(attempt).resolve(),Path(output).resolve()
    if output.exists() or (attempt/'result.json').exists():
        raise ValueError('Retain original finalization; use a fresh attempt')
    config=json.loads(required(attempt,'config.json').read_text())
    count=config['duration_s']*config['rate_hz']
    if count!=240:raise ValueError('Full 12-second pedestrian window changed')
    joins=verify_original_joins(attempt,count)
    report=analysis_report(attempt)
    observed=report['measurements']['right_half_passage']['value']
    context=json.loads(required(attempt,'crosswalk-context.json').read_text())
    expected='right' if config['case_suffix']=='reference' else 'left'
    videos={}
    for camera in config['cameras']:
        name=camera['name']+'.mkv'
        info=video_info(attempt/name)
        if info!=(count,camera['width'],camera['height']):
            raise ValueError('Source camera frame count or dimensions differ: '+name)
        videos[name]={'frames':info[0],'width':info[1],'height':info[2]}
    evidence=[]
    for channel in config['recording_description']['channels']:
        ref='channels/'+channel['name']+'.jsonl'
        required(attempt,ref)
        evidence.append({'name':channel['name'],'unit':channel['unit'],'reference':ref})
    for item in config['recording_description']['context_inputs']:
        evidence.append({'name':item['name'],'unit':item['unit'],
                         'reference':'crosswalk-context.json'})
    measured=observed['observed_half']
    result={'case_id':config['case_id'],
            'measured_values':{'observed_crosswalk_half':measured,
                               'crosswalk_frames':observed['crosswalk_frames'],
                               'passage_duration_s':observed['passage_duration_s']},
            'target_checks':[{'target':'full-window crosswalk half','requested':expected,
                'measured':measured,'method':'original pedestrian footprints across joined Native frames',
                'tolerance':0,'matched':measured==expected,
                'physical_cause_confirmed':False,
                'cause_evidence':['native_samples.jsonl','crosswalk-context.json','trace.jsonl']}],
            'setup_confirmed':False,
            'behavior_attempted':context['source_kind']=='native_observation',
            'maneuver_completed':context['source_kind']=='native_observation' and measured==expected,
            'termination_reason':'full original source interval retained',
            'physical_failure_flags':['practicability_and_original_pixels_unverified'],
            'trace_reference':'trace.jsonl','video_references':list(videos),
            'video_frame_map_reference':'video_frames.jsonl',
            'recording_description':config['recording_description'],
            'recording_evidence':evidence,
            'realized_observables':{'pedestrian_right_half_fraction':{
                'value':observed['crosswalk_half_counts']['right']/observed['crosswalk_frames'],
                'unit':'ratio',
                'method':'original four-vertex footprints within crosswalk geometry',
                'time_window':'entire original 12-second passage','statistic':'fraction of fully contained frames',
                'reference':'native_samples.jsonl'}},
            'provenance_kind':('synthetic_local_diagnostic' if context['source_kind']=='synthetic_scene_request'
                               else 'native_source_shape_unverified'),
            'accepted':False,'legal_verdict_claimed':False}
    validate_result(result)
    report.update(format='c10316-saved-crosswalk-analysis-v1',
                  candidate_id=config['candidate_id'],original_joins=joins,
                  video_frames=videos,
                  scope='saved original-source joins and video decode; no practicability or legal finding')
    output.write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')
    (attempt/'result.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    return report


if __name__=='__main__':
    import argparse
    parser=argparse.ArgumentParser()
    parser.add_argument('--attempt',required=True);parser.add_argument('--output',required=True)
    args=parser.parse_args()
    print(json.dumps(finalize(args.attempt,args.output),allow_nan=False))
